(() => {
  'use strict';
  const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n;};
  const key='good-vibes-bootstrap-v1',base=document.body.dataset.base,absoluteBase=new URL(base,location.origin).href;
  const internal=path=>base.replace(/\/$/,'')+'/'+path.replace(/^\//,'');
  const link=(text,url)=>{const a=el('a','',text);a.href=url;if(/^https?:/.test(url)){a.target='_blank';a.rel='noopener';}return a;};
  const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const defaults=()=>({schema:1,step:0,project:{name:'',type:'web',goal:'',stack:'',repository:'new',environment:'',constraints:''},rules:{timing:'selected',ci:'none',isolation:'local',retries:'2',review:true,notes:''},selected:[]});
  let state=defaults(),catalog,recipes,entities,limit=18,storageAvailable=true;
  const filters={q:'',stage:'build',entity:'all',mode:'all',selected:false};
  const fields={name:'project-name',type:'project-type',goal:'project-goal',stack:'project-stack',repository:'project-repository',environment:'project-environment',constraints:'project-constraints'};
  const rules={timing:'rule-timing',ci:'rule-ci',isolation:'rule-isolation',retries:'rule-retries',review:'rule-review',notes:'rule-notes'};
  function save(){try{localStorage.setItem(key,JSON.stringify(state));$('draft-status').textContent='Draft saved in this browser.';}catch{$('draft-status').textContent='Browser storage is unavailable. You can still download this session’s prompt.';storageAvailable=false;}}
  function restore(){try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft?.schema===1){for(const k of Object.keys(fields))if(typeof draft.project?.[k]==='string')state.project[k]=draft.project[k];for(const k of Object.keys(rules))if(typeof draft.rules?.[k]===typeof state.rules[k])state.rules[k]=draft.rules[k];state.selected=Array.isArray(draft.selected)?[...new Set(draft.selected.filter(id=>catalog.items.some(i=>i.id===id)))]:[];state.step=Number.isInteger(draft.step)&&draft.step>=0&&draft.step<=3?draft.step:0;}}catch{storageAvailable=false;}}
  function populate(){for(const [k,id] of Object.entries(fields)){const input=$(id);input.value=state.project[k];if(input.tagName==='SELECT'&&!input.value){state.project[k]=defaults().project[k];input.value=state.project[k];}}for(const [k,id] of Object.entries(rules)){const input=$(id);if(k==='review')input.checked=state.rules[k];else{input.value=state.rules[k];if(input.tagName==='SELECT'&&!input.value){state.rules[k]=defaults().rules[k];input.value=state.rules[k];}}}}
  function info(){return window.BootstrapPrompt.analyze(state,catalog,recipes);}
  function recipeFor(item){return recipes.items[item.id]||{mode:'research',instructions:['Verify an authoritative public setup path or record the item as deferred.']};}
  function toggle(id,value){if(value&&!state.selected.includes(id))state.selected.push(id);if(!value)state.selected=state.selected.filter(x=>x!==id);save();renderSelections();renderItems();renderIssues();if(state.step===3)preview();}
  function renderSelections(){const chosen=catalog.items.filter(i=>state.selected.includes(i.id));$('selection-count').textContent=chosen.length;$('selection-help').textContent=chosen.length?'Selected across '+new Set(chosen.map(i=>i.stage)).size+' pipeline stages. Remove anything that has no job.':'Start small. Every selection should have a job.';$('selected-list').replaceChildren(...chosen.map(i=>{const row=el('div','selection-row'),text=el('div','',i.name);text.append(el('small','',window.BootstrapPrompt.modes[recipeFor(i).mode]));const b=el('button','','×');b.type='button';b.setAttribute('aria-label','Remove '+i.name);b.addEventListener('click',()=>toggle(i.id,false));row.append(text,b);return row;}));}
  function renderItems(){const focus=document.activeElement?.id;const terms=normalize(filters.q).split(/\s+/).filter(Boolean);const matches=catalog.items.filter(i=>{const recipe=recipeFor(i);if(filters.stage!=='all'&&i.stage!==filters.stage||filters.mode!=='all'&&recipe.mode!==filters.mode||filters.selected&&!state.selected.includes(i.id))return false;const obs=i.observations.filter(o=>filters.entity==='all'||filters.entity===o.entity||filters.entity===entities.get(o.entity)?.kind);if(!obs.length)return false;const hay=normalize([i.name,i.usage,i.type,...obs.map(o=>[entities.get(o.entity)?.name,o.claim,o.kind,o.qualification].join(' '))].join(' '));return terms.every(t=>hay.includes(t));});
    $('filter-status').textContent=`${matches.length} matching entries · ${state.selected.length} selected · catalogue reviewed ${catalog.reviewed}`;
    const list=$('item-list');list.replaceChildren();if(!matches.length){list.append(el('p','empty-list','No matching entries. Clear the search or broaden the stage, person and availability filters.'));return;}
    for(const item of matches.slice(0,limit)){const recipe=recipeFor(item),card=el('article','capability'+(state.selected.includes(item.id)?' is-selected':''));const label=el('label','capability-top');const check=el('input');check.type='checkbox';check.id='pick-'+item.id;check.checked=state.selected.includes(item.id);check.setAttribute('aria-label','Select '+item.name);check.addEventListener('change',()=>toggle(item.id,check.checked));const content=el('div');content.append(el('p','kind',(catalog.stages.find(s=>s.id===item.stage)?.name||item.stage)+' / '+item.type),el('h3','',item.name),el('p','usage',item.usage),el('span','availability '+recipe.mode,window.BootstrapPrompt.modes[recipe.mode]));label.append(check,content);card.append(label);
      card.append(el('p','attribution-names',[...new Set(item.observations.map(o=>entities.get(o.entity)?.name))].join(' · ')));
      const setup=el('details');setup.append(el('summary','','Setup treatment & sourced evidence'));const instructions=el('ol');recipe.instructions.forEach(s=>instructions.append(el('li','',s)));setup.append(instructions);
      item.observations.forEach(o=>{const entry=el('div','evidence-entry');entry.append(el('strong','',(entities.get(o.entity)?.name||o.entity)+' · '+o.kind),el('p','',o.claim),el('p','evidence-limit',o.qualification),el('p','evidence-limit','Published / revision: '+o.published+' · practice: '+o.practice+' · checked: '+o.checked),link('Primary evidence ↗',o.source),link('Cached context',internal(o.detail)));setup.append(entry);});card.append(setup);list.append(card);
    }
    if(matches.length>limit){const more=el('button','',`Show ${Math.min(18,matches.length-limit)} more (${matches.length-limit} remaining)`);more.type='button';more.addEventListener('click',()=>{limit+=18;renderItems();});list.append(more);}
    if(focus?.startsWith('pick-'))$(focus)?.focus({preventScroll:true});
  }
  function renderIssues(){const a=info();for(const id of ['rule-issues','export-issues']){const box=$(id);box.replaceChildren();a.errors.forEach(msg=>{const n=el('div','issue error',msg);if(msg.includes('conflict')){const removeAfter=state.selected.includes('verify-4');const b=el('button','',removeAfter?'Remove “Tests after implementation”':'Use the timing of selected practices');b.type='button';b.addEventListener('click',()=>{if(removeAfter)toggle('verify-4',false);else{state.rules.timing='selected';$('rule-timing').value='selected';save();renderIssues();if(state.step===3)preview();}});n.append(b);}box.append(n);});a.notes.forEach(msg=>box.append(el('p','issue',msg)));}const blocked=a.errors.length>0;$('download').disabled=blocked;$('copy-prompt').disabled=blocked;return a;}
  function preview(){$('prompt-preview').value=window.BootstrapPrompt.generate(state,catalog,recipes,absoluteBase);renderIssues();$('export-status').textContent=info().errors.length?'Resolve the issues above before exporting.':`${state.selected.length} selected entries · setup instructions, evidence and completion checks included.`;}
  function navigate(step,focus=true){state.step=step;document.querySelector('.wizard-content').classList.toggle('is-curating',step===1);document.querySelectorAll('[data-wizard-step]').forEach(b=>{if(Number(b.dataset.wizardStep)===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});for(let i=0;i<4;i++)$('step-'+i).hidden=i!==step;$('previous').disabled=step===0;$('next').hidden=step===3;$('next').textContent=['Choose tools →','Set working rules →','Review prompt →',''][step];$('step-status').textContent='Step '+(step+1)+' of 4';if(step===1)renderItems();if(step===2)renderIssues();if(step===3)preview();save();if(focus){const heading=$('step-'+step).querySelector('h2');heading.tabIndex=-1;heading.focus({preventScroll:true});$('steps').scrollIntoView({block:'start',behavior:'auto'});}}
  function next(){if(state.step===0&&!$('project-form').reportValidity())return;navigate(Math.min(3,state.step+1));}
  async function boot(){try{const responses=await Promise.all([fetch(document.body.dataset.catalog),fetch(document.body.dataset.recipes)]);if(responses.some(r=>!r.ok))throw Error('The catalogue or setup recipes could not load.');[catalog,recipes]=await Promise.all(responses.map(r=>r.json()));if(catalog.schema!==1||recipes.schema!==1||!Array.isArray(catalog.items))throw Error('Unsupported catalogue format.');entities=new Map(catalog.entities.map(e=>[e.id,e]));restore();populate();
      ['Project brief','Curate tools','Working rules','Export prompt'].forEach((name,i)=>{const b=el('button');b.type='button';b.dataset.wizardStep=i;b.append(el('span','',String(i+1).padStart(2,'0')),document.createTextNode(name));b.addEventListener('click',()=>navigate(i));$('steps').append(b);});
      catalog.stages.forEach(s=>{const o=el('option','',s.name);o.value=s.id;$('item-stage').append(o);});$('item-stage').value=filters.stage;for(const kind of ['individual','company']){const group=el('optgroup');group.label=kind==='individual'?'Engineers':'Companies';catalog.entities.filter(e=>e.kind===kind&&e.observations>0).sort((a,b)=>a.name.localeCompare(b.name)).forEach(e=>{const o=el('option','',e.name);o.value=e.id;group.append(o);});$('item-entity').append(group);}
      for(const [k,id] of Object.entries(fields))$(id).addEventListener($(id).tagName==='SELECT'?'change':'input',()=>{state.project[k]=$(id).value;save();renderIssues();});
      for(const [k,id] of Object.entries(rules))$(id).addEventListener($(id).tagName==='SELECT'||k==='review'?'change':'input',()=>{state.rules[k]=k==='review'?$(id).checked:$(id).value;save();renderIssues();});
      $('project-form').addEventListener('submit',e=>{e.preventDefault();next();});$('next').addEventListener('click',next);$('previous').addEventListener('click',()=>navigate(Math.max(0,state.step-1)));
      for(const [id,k,event] of [['item-search','q','input'],['item-stage','stage','change'],['item-entity','entity','change'],['item-mode','mode','change'],['only-selected','selected','change']])$(id).addEventListener(event,()=>{filters[k]=k==='selected'?$(id).checked:$(id).value;if(k==='q'&&filters.q.trim()){filters.stage='all';$('item-stage').value='all';}limit=18;renderItems();});
      $('starter').addEventListener('click',()=>{for(const id of ['define-3','plan-1','context-6','verify-10','review-5'])if(!state.selected.includes(id))state.selected.push(id);save();renderSelections();renderItems();renderIssues();});
      $('reset-draft').addEventListener('click',()=>{state=defaults();Object.assign(filters,{q:'',stage:'build',entity:'all',mode:'all',selected:false});$('item-search').value='';$('item-stage').value='build';$('item-entity').value='all';$('item-mode').value='all';$('only-selected').checked=false;limit=18;populate();renderSelections();renderItems();renderIssues();navigate(0);});
      $('download').addEventListener('click',()=>{if(info().errors.length)return;preview();const blob=new Blob([$('prompt-preview').value],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='bootstrap-prompt.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('export-status').textContent='Downloaded bootstrap-prompt.md. Hand this file to your setup agent.';});
      $('copy-prompt').addEventListener('click',async()=>{if(info().errors.length)return;preview();try{await navigator.clipboard.writeText($('prompt-preview').value);$('export-status').textContent='Prompt copied.';}catch{$('prompt-preview').focus();$('prompt-preview').select();$('export-status').textContent='Clipboard access is unavailable. The prompt is selected; copy it manually or download the Markdown file.';}});
      $('load-status').textContent=`${catalog.items.length} sourced entries · ${catalog.entities.length} profiles · ${state.selected.length?'draft restored':'start with your own selection'}`;$('wizard-app').hidden=false;renderSelections();renderIssues();navigate(state.step,false);if(!storageAvailable)$('draft-status').textContent='Browser storage is unavailable; download your prompt to keep it.';
    }catch(error){$('load-status').textContent=error.message+' Reload to retry, or browse the evidence atlas.';$('load-status').append(document.createTextNode(' '),link('Open atlas',internal('/pipeline/')));}}
  boot();
})();
